    /// <summary>
    /// Delete Tables
    /// </summary>
    protected void deleteTables()
    {
        METPriceChangeInquiry       priceChangeInquiry;

        GUPPriceReportExpirationDate utcEndOfDay = DateTimeUtil::getSystemDate(DateTimeUtil::getUserPreferredTimeZone());

        ttsbegin;

        delete_from priceChangeInquiry
            where priceChangeInquiry.RetentionExpirationDate < utcEndOfDay;

        ttscommit;
    }

/// <summary>
/// Construct the class
/// </summary>
/// <returns>METPriceChangeInquiryBasePriceCleanUp</returns>
static METPriceChangeInquiryBasePriceCleanUp construct()
{
    return new METPriceChangeInquiryBasePriceCleanUp();
}

    /// <summary>
    /// Main 
    /// </summary>
    /// <param name = "_args">args</param>
    static void main(Args _args)
    {
        METPriceChangeInquiryBasePriceCleanUp priceChangeInquiryCleanUp = METPriceChangeInquiryBasePriceCleanUp::newStandard(_args);

        if (!priceChangeInquiryCleanUp.prompt())
        {
            return;
        }

        priceChangeInquiryCleanUp.runOperation();
    }

    /// <summary>
    /// New standard
    /// </summary>
    /// <param name = "_args">args</param>
    /// <returns>METPriceChangeInquiryBasePriceCleanUp</returns>
    static METPriceChangeInquiryBasePriceCleanUp newStandard(Args _args)
    {
        METPriceChangeInquiryBasePriceCleanUp priceChangeInquiryCleanUp = METPriceChangeInquiryBasePriceCleanUp::construct();
        priceChangeInquiryCleanUp.getLast();
        priceChangeInquiryCleanUp.init();

        return priceChangeInquiryCleanUp;
    }
